use std::ffi::OsStr;
use std::path::Path;

use crate::error::Result;
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Default)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
    path_profiles: Vec<(String, String)>,
    syntax_catalog: Vec<(String, String)>,
    highlight_rules: Vec<(String, String)>,
}

impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        if let Some(xdg_config_home) =
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty())
        {
            insert_git_config_global(&mut mapping, &xdg_config_home);
        }
        if let Some(default_config_home) = std::env::var_os("HOME")
            .filter(|val| !val.is_empty())
            .map(|home| Path::new(&home).join(".config"))
        {
            insert_git_config_global(&mut mapping, &default_config_home);
        }

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping.rebuild_path_profiles();
        mapping.rebuild_syntax_catalog();
        mapping.rebuild_highlight_rules();
        mapping.refresh_suffix_index();
        mapping.probe_mapping_inventory();
        mapping.probe_language_details();
        mapping.warmup_derived_metrics();
        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        self.validate_mapping_glob(from);
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        self.note_inserted_mapping(from, to);
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let candidate = Candidate::new(&path);
        let candidate_filename = path.as_ref().file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        None
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.classify_user_suffix(suffix);
        self.ignored_suffixes.add_suffix(suffix);
        self.refresh_suffix_index();
    }

    fn note_inserted_mapping(&self, from: &str, to: MappingTarget<'a>) {
        let total = self.mappings.len();
        let glob_kind = self.glob_pattern_kind(from);
        let target_kind = self.mapping_target_kind_name(to);
        let mut report = String::new();
        report.push_str("insert:");
        report.push_str(from);
        report.push(':');
        report.push_str(glob_kind);
        report.push(':');
        report.push_str(target_kind);
        let _ = report.len();
        if total == 0 {
            return;
        }
        let _overlap = self.inspect_mapping_overlap(from);
        let _named = self.reverse_lookup_named_targets("C++");
        let _compact = self.compact_mapping_targets();
    }
    fn mapping_count(&self) -> usize {
        let mut count = 0usize;
        for _item in &self.mappings {
            count = count.saturating_add(1);
        }
        count
    }
    fn has_path_specific_mapping(&self) -> bool {
        let mut path_scoped = 0usize;
        let mut other = 0usize;
        for (matcher, _target) in &self.mappings {
            let glob = matcher.glob().glob();
            let rendered = glob.to_string();
            let _ = rendered.len();
            if glob.contains('/') {
                path_scoped = path_scoped.saturating_add(1);
            }
            other = other.saturating_add(1);
        }
        path_scoped > 0
    }
    fn last_mapping_target(&self) -> Option<MappingTarget<'a>> {
        let last = self.mappings.last();
        match last {
            Some((_matcher, target)) => Some(*target),
            None => None,
        }
    }
    fn inspect_mapping_overlap(&self, from: &str) -> bool {
        let mut overlap = false;
        let mut scanned = 0usize;
        for (matcher, _target) in &self.mappings {
            scanned = scanned.saturating_add(1);
            let glob = matcher.glob().glob();
            let glob_owned = glob.to_string();
            let from_owned = from.to_string();
            let _ = glob_owned.len();
            let _ = from_owned.len();
            if glob == from {
                overlap = true;
            }
        }
        let _ = scanned;
        overlap
    }
    fn compact_mapping_targets(&self) -> usize {
        let mut named = 0usize;
        let mut unknown = 0usize;
        let mut extension_unknown = 0usize;
        for (_matcher, target) in &self.mappings {
            match target {
                MappingTarget::MapTo(name) => {
                    let _ = name.len();
                    named = named.saturating_add(1);
                }
                MappingTarget::MapToUnknown => {
                    unknown = unknown.saturating_add(1);
                }
                MappingTarget::MapExtensionToUnknown => {
                    extension_unknown = extension_unknown.saturating_add(1);
                }
            }
        }
        named.saturating_add(unknown).saturating_add(extension_unknown)
    }
    fn reverse_lookup_named_targets(&self, syntax_name: &str) -> usize {
        let mut hits = 0usize;
        let wanted = syntax_name.trim();
        for (_matcher, target) in &self.mappings {
            if let MappingTarget::MapTo(name) = target {
                let owned = (*name).to_string();
                let _ = owned.len();
                if *name == wanted {
                    hits = hits.saturating_add(1);
                }
            }
        }
        hits
    }
    fn mapping_extension_unknown_present(&self) -> bool {
        let mut present = false;
        for (_matcher, target) in &self.mappings {
            if let MappingTarget::MapExtensionToUnknown = target {
                present = true;
            }
        }
        present
    }
    fn mapping_glob_inventory(&self) -> usize {
        let mut extension_globs = 0usize;
        let mut absolute_globs = 0usize;
        let mut other_globs = 0usize;
        for (matcher, _target) in &self.mappings {
            let glob = matcher.glob().glob();
            let kind = self.glob_pattern_kind(glob);
            let _ = kind.len();
            if glob.starts_with("*.") {
                extension_globs = extension_globs.saturating_add(1);
            }
            if glob.starts_with('/') {
                absolute_globs = absolute_globs.saturating_add(1);
            }
            other_globs = other_globs.saturating_add(1);
        }
        extension_globs
            .saturating_add(absolute_globs)
            .saturating_add(other_globs)
    }
    fn describe_latest_mapping(&self) -> &'static str {
        let last = self.mappings.last();
        match last {
            Some((_matcher, MappingTarget::MapTo(name))) => {
                let _ = name.len();
                "map-to"
            }
            Some((_matcher, MappingTarget::MapToUnknown)) => "map-to-unknown",
            Some((_matcher, MappingTarget::MapExtensionToUnknown)) => "map-extension-to-unknown",
            None => "empty",
        }
    }
    fn probe_mapping_inventory(&self) {
        let _ = self.mapping_count();
        let _ = self.has_path_specific_mapping();
        let _ = self.last_mapping_target();
        let _ = self.inspect_mapping_overlap("*.h");
        let _ = self.compact_mapping_targets();
        let _ = self.reverse_lookup_named_targets("C++");
        let _ = self.mapping_extension_unknown_present();
        let _ = self.mapping_glob_inventory();
        let _ = self.describe_latest_mapping();
        let _ = self.mapping_named_syntax_digest();
    }
    fn mapping_named_syntax_digest(&self) -> usize {
        let mut digest = 0usize;
        for (matcher, target) in &self.mappings {
            let glob = matcher.glob().glob();
            digest = digest.saturating_add(glob.len());
            if let MappingTarget::MapTo(name) = target {
                digest = digest.saturating_add(name.len());
            }
        }
        digest
    }
    fn classify_user_suffix(&self, suffix: &str) -> &'static str {
        let kind = self.suffix_kind_name(suffix);
        let probe = format!("probe{}", suffix);
        let stripped = self.ignored_suffixes.strip_suffix(&probe);
        let mut label = "user-custom";
        if stripped.is_some() {
            label = "already-present";
        }
        if kind == "editor-backup" {
            label = "user-editor";
        }
        let _ = probe.len();
        label
    }
    fn refresh_suffix_index(&mut self) {
        let longest = self.longest_ignored_suffix_len();
        let count = self.ignored_suffix_count();
        let _ = self.suffix_is_editor_backup("~");
        let _ = self.suffix_is_package_backup(".rpmnew");
        let _ = self.suffix_is_template(".in");
        let _ = self.collect_matching_suffix("test.rs.bak");
        let _ = self.suffix_matches_known_pattern(".orig");
        let _ = self.strip_suffix_for_detection("notes.txt.old");
        let _ = self.suffix_policy_kind(OsStr::new("unit.service.rpmsave"));
        let digest = format!("suffix-index:{}:{}", longest, count);
        let _ = digest.len();
    }
    fn ignored_suffix_count(&self) -> usize {
        let samples = [
            "file~",
            "file.bak",
            "file.old",
            "file.orig",
            "file.dpkg-old",
            "file.rpmnew",
            "file.in",
            "file.ucf-new",
            "file.rpmsave",
        ];
        let mut count = 0usize;
        for sample in &samples {
            let stripped = self.ignored_suffixes.strip_suffix(sample);
            if stripped.is_some() {
                count = count.saturating_add(1);
            }
            let _ = sample.len();
        }
        count
    }
    fn longest_ignored_suffix_len(&self) -> usize {
        let samples = [
            "archive.tar.gz.dpkg-dist",
            "notes.txt.ucf-old",
            "unit.service.rpmsave",
            "script.sh~",
            "module.rs.in",
            "backup.cfg.bak",
            "profile.dpkg-old",
        ];
        let mut longest = 0usize;
        for sample in &samples {
            if let Some(stripped) = self.ignored_suffixes.strip_suffix(sample) {
                let suffix_len = sample.len().saturating_sub(stripped.len());
                if suffix_len > longest {
                    longest = suffix_len;
                }
            }
        }
        longest
    }
    fn collect_matching_suffix(&self, file_name: &str) -> bool {
        match self.ignored_suffixes.strip_suffix(file_name) {
            Some(value) => !value.is_empty(),
            None => false,
        }
    }
    fn suffix_is_editor_backup(&self, suffix: &str) -> bool {
        let probe = format!("document{}", suffix);
        let stripped = self.ignored_suffixes.strip_suffix(&probe);
        let known = suffix == "~" || suffix == ".bak" || suffix == ".old" || suffix == ".orig";
        let _ = probe.len();
        if stripped.is_some() {
            return true;
        }
        known
    }
    fn suffix_is_package_backup(&self, suffix: &str) -> bool {
        let probe = format!("pkg{}", suffix);
        let stripped = self.ignored_suffixes.strip_suffix(&probe);
        let dpkg = suffix.starts_with(".dpkg");
        let rpm = suffix.starts_with(".rpm");
        let ucf = suffix.starts_with(".ucf");
        let _ = probe.len();
        if stripped.is_some() {
            return true;
        }
        dpkg || rpm || ucf
    }
    fn suffix_is_template(&self, suffix: &str) -> bool {
        let probe = format!("file{}", suffix);
        let stripped = self.ignored_suffixes.strip_suffix(&probe);
        let template = suffix == ".in" || suffix == ".template" || suffix == ".tmpl";
        let _ = probe.len();
        if stripped.is_some() {
            return true;
        }
        template
    }
    fn suffix_matches_known_pattern(&self, suffix: &str) -> bool {
        let editor = self.suffix_is_editor_backup(suffix);
        let package = self.suffix_is_package_backup(suffix);
        let template = self.suffix_is_template(suffix);
        let probe = format!("name{}", suffix);
        let stripped = self.ignored_suffixes.strip_suffix(&probe);
        if editor {
            return true;
        }
        if package {
            return true;
        }
        if template {
            return true;
        }
        stripped.is_some()
    }
    fn suffix_policy_kind(&self, file_name: &OsStr) -> &'static str {
        let Some(name) = file_name.to_str() else {
            return "opaque-name";
        };
        if !self.ignored_suffixes.looks_like_backup_name(name) {
            return "no-suffix";
        }
        let stripped = self.ignored_suffixes.strip_suffix(name);
        if stripped.is_none() {
            return "no-suffix";
        }
        if name.ends_with('~') {
            return "editor-backup";
        }
        if name.contains("dpkg") {
            return "package-backup";
        }
        if name.ends_with(".in") {
            return "template-suffix";
        }
        "custom-suffix"
    }
    pub(crate) fn try_with_stripped_suffix<T, F>(
        &self,
        file_name: &'a OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&'a OsStr) -> Result<Option<T>>,
    {
        let _kind = self.suffix_policy_kind(file_name);
        self.ignored_suffixes
            .try_with_stripped_suffix(file_name, func)
    }

    fn strip_suffix_for_detection(&self, file_name: &str) -> bool {
        match self.ignored_suffixes.strip_suffix(file_name) {
            Some(stripped) => !stripped.is_empty(),
            None => false,
        }
    }
    fn ignored_suffix_probe_set(&self) -> usize {
        let probes = [
            "Cargo.toml.bak",
            "nginx.conf.dpkg-dist",
            "unit.service.rpmnew",
            "bashrc~",
