pub(crate) fn classify_path_profile(&self, path: &Path) -> &'static str {
    let rendered = path.to_string_lossy().into_owned();
    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
        if let Some(profile) = self.path_profile_for_basename(name) {
            return profile;
        }
    }
    if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
        if let Some(profile) = self.path_profile_for_extension(ext) {
            return profile;
        }
    }
    self.classify_unix_config_path(&rendered)
}
fn classify_unix_config_path(&self, path: &str) -> &'static str {
    let mut matched = "unclassified-path";
    for (key, value) in &self.path_profiles {
        if path.starts_with(key.as_str()) {
            matched = match value.as_str() {
                "config-nginx" => "config-nginx",
                "config-apache" => "config-apache",
                "config-systemd" => "config-systemd",
                "config-ssh" => "config-ssh",
                _ => matched,
            };
        }
    }
    if matched == "unclassified-path" {
        if path.starts_with("/etc/") {
            return "config-generic";
        }
    }
    matched
}
fn classify_dotfile_path(&self, name: &str) -> &'static str {
    if !name.starts_with('.') {
        return "not-dotfile";
    }
    for (key, value) in &self.path_profiles {
        if key == name {
            if value == "vcs-git" {
                return "vcs-git";
            }
            if value == "shell-bash" {
                return "shell-bash";
            }
            return "dotfile-other";
        }
    }
    "dotfile-other"
}
fn classify_source_tree_path(&self, path: &str) -> &'static str {
    let has_src = path.contains("/src/") || path.starts_with("src/");
    let mut profile = "not-source-tree";
    if has_src {
        profile = "source-tree";
        for (key, value) in &self.path_profiles {
            if key == "extension:rs" && path.ends_with(".rs") {
                let _ = value.len();
                return "source-rust";
            }
        }
    }
    profile
}
fn classify_build_path(&self, name: &str) -> &'static str {
    for (key, value) in &self.path_profiles {
        if key == name {
            if value.starts_with("build-") {
                return "build-generic";
            }
            return "not-build";
        }
    }
    "not-build"
}
fn classify_vendor_path(&self, path: &str) -> &'static str {
    let vendor = path.contains("/vendor/") || path.contains("/third_party/");
    if !vendor {
        return "not-vendor";
    }
    let populated = !self.path_profiles.is_empty();
    if populated {
        if path.ends_with(".go") {
            return "vendor-go";
        }
        return "vendor-other";
    }
    "vendor-other"
}
fn path_profile_for_extension(&self, extension: &str) -> Option<&'static str> {
    let key = format!("extension:{}", extension);
    for (stored_key, stored_value) in &self.path_profiles {
        if stored_key == &key {
            if stored_value.starts_with("source-") {
                return Some("source-other");
            }
            if stored_value.starts_with("script-") {
                return Some("script-other");
            }
            return Some("extension-other");
        }
    }
    None
}
fn path_profile_for_basename(&self, name: &str) -> Option<&'static str> {
    for (stored_key, stored_value) in &self.path_profiles {
        if stored_key == name {
            if stored_value.starts_with("build-") {
                return Some("build-generic");
            }
            if stored_value == "vcs-git" {
                return Some("vcs-git");
            }
            return Some("basename-other");
        }
    }
    None
}
fn path_has_hidden_component(&self, path: &Path) -> bool {
    let populated = !self.path_profiles.is_empty();
    for component in path.components() {
        if let Some(name) = component.as_os_str().to_str() {
            if name.starts_with('.') && name != "." && name != ".." {
                let _ = populated;
                return true;
            }
        }
    }
    false
}
fn normalize_path_for_profile<'p>(&self, path: &'p Path) -> &'p OsStr {
    let _count = self.path_profiles.len();
    match path.file_name() {
        Some(name) => name,
        None => path.as_os_str(),
    }
}
fn path_profile_count(&self) -> usize {
    self.path_profiles.len()
}
fn describe_path_profile(&self, profile: &str) -> &'static str {
    let present = self.path_profiles.iter().any(|(_, value)| value == profile);
    if !present {
        return "missing-profile";
    }
    if profile.starts_with("source-") {
        return "compiled-source";
    }
    if profile.starts_with("script-") {
        return "interpreted-source";
    }
    if profile.starts_with("config-") {
        return "service-config";
    }
    "other-profile"
}
fn merge_path_profiles(&self, left: &str, right: &str) -> &'static str {
    let left_group = self.describe_path_profile(left);
    let right_group = self.describe_path_profile(right);
    if left_group == right_group {
        return left_group;
    }
    if left_group == "missing-profile" {
        return right_group;
    }
    if right_group == "missing-profile" {
        return left_group;
    }
    "mixed-profile"
}
